"use client";

import {
  createContext,
  useContext,
  useState,
  ReactNode,
} from "react";

type FlightConfirmationState = {
  open: boolean;
  droneId: string;
};

type FlightConfirmationContextType = {
  flightConfirmation: FlightConfirmationState;
  showFlightConfirmation: (droneId: string) => void;
  hideFlightConfirmation: () => void;
};

const FlightConfirmationContext =
  createContext<FlightConfirmationContextType | null>(null);

export function FlightConfirmationProvider({
  children,
}: {
  children: ReactNode;
}) {
  const [flightConfirmation, setFlightConfirmation] = useState({
    open: false,
    droneId: "",
  });

  const showFlightConfirmation = (droneId: string) => {
    setFlightConfirmation({
      open: true,
      droneId,
    });
  };

  const hideFlightConfirmation = () => {
    setFlightConfirmation({
      open: false,
      droneId: "",
    });
  };

  return (
    <FlightConfirmationContext.Provider
      value={{
        flightConfirmation,
        showFlightConfirmation,
        hideFlightConfirmation,
      }}
    >
      {children}
    </FlightConfirmationContext.Provider>
  );
}

export function useFlightConfirmation() {
  const context = useContext(FlightConfirmationContext);

  if (!context) {
    throw new Error(
      "useFlightConfirmation must be used inside FlightConfirmationProvider"
    );
  }

  return context;
}